<script setup lang="ts">
import { computed, reactive, ref, watch } from "vue";
import StudentImportCredentials from "../../components/StudentImportCredentials.vue";
import { useRoute, useRouter } from "vue-router";
import { ElMessage, ElMessageBox } from "element-plus";
import { adminDelete, adminGet, adminPost, adminPut } from "../../../admin/api/adminClient";
import { adminPath } from "../../../utils/adminPath";
import { formatDisplayDateTime } from "../../../lib/format";

type Member = { userId: number; username?: string; displayName?: string; studentNo?: string; email?: string; source?: string; joinedAt: string };
type Classroom = { id: number; name: string; description?: string; teacherId: number; teacherName?: string; memberCount: number; joinEnabled: boolean; approvalRequired: boolean; createdAt: string; members?: Member[] };
type Teacher = { id: number; username: string; displayName: string };
type ImportResult = { successCount: number; failureCount: number; successes?: Array<{ studentNo?: string; displayName?: string; initialPassword?: string | null }>; errors: Array<{ rowNumber: number; studentNo?: string; reason: string }> };
const route=useRoute();const router=useRouter();const classId=computed(()=>Number(route.params.classId)||null);
const rows=ref<Classroom[]>([]);const detail=ref<Classroom|null>(null);const teachers=ref<Teacher[]>([]);const loading=ref(false);const teacherLoading=ref(false);const keyword=ref("");const searchText=ref("");const dialog=ref(false);const importDialog=ref(false);const editing=ref<Classroom|null>(null);const saving=ref(false);const importing=ref(false);const file=ref<File|null>(null);const importResult=ref<ImportResult|null>(null);
const form=reactive({name:"",description:"",teacherId:undefined as number|undefined,joinEnabled:true,approvalRequired:true});const importForm=reactive({classId:undefined as number|undefined,studentNoField:"学号",nameField:"姓名"});
async function load(){loading.value=true;try{if(classId.value){detail.value=await adminGet<Classroom>(`/api/admin/v1/classes/${classId.value}`);return;}const params=new URLSearchParams();if(keyword.value.trim())params.set("keyword",keyword.value.trim());rows.value=await adminGet<Classroom[]>(`/api/admin/v1/classes?${params.toString()}`);}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"班级数据加载失败");}finally{loading.value=false;}}
async function loadTeachers(query="",required?:Teacher){teacherLoading.value=true;try{const params=new URLSearchParams();if(query.trim())params.set("keyword",query.trim());const result=await adminGet<Teacher[]>(`/api/admin/v1/teachers?${params.toString()}`);teachers.value=required&&!result.some(item=>item.id===required.id)?[required,...result]:result;}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"教师列表加载失败");}finally{teacherLoading.value=false;}}
function openCreate(){editing.value=null;Object.assign(form,{name:"",description:"",teacherId:undefined,joinEnabled:true,approvalRequired:true});dialog.value=true;void loadTeachers();}
function openEdit(item:Classroom){editing.value=item;Object.assign(form,{name:item.name,description:item.description??"",teacherId:item.teacherId,joinEnabled:item.joinEnabled,approvalRequired:item.approvalRequired});void loadTeachers(item.teacherName??"",{id:item.teacherId,username:"",displayName:item.teacherName??""});dialog.value=true;}
async function save(){if(!form.name.trim()){ElMessage.warning("请输入班级名称");return;}if(!form.teacherId){ElMessage.warning("请选择教师");return;}saving.value=true;try{const body={name:form.name.trim(),description:form.description.trim()||undefined,teacherId:form.teacherId,joinEnabled:form.joinEnabled,approvalRequired:form.approvalRequired};if(editing.value)await adminPut(`/api/admin/v1/classes/${editing.value.id}`,body);else await adminPost("/api/admin/v1/classes",body);ElMessage.success(editing.value?"班级已更新":"班级已创建");dialog.value=false;await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"保存失败");}finally{saving.value=false;}}
async function deleteClass(item:Classroom){try{await ElMessageBox.confirm(`确认删除班级 ${item.name}？学生主班级、申请和班级受众会同步清理。`,"删除班级",{type:"warning"});await adminDelete(`/api/admin/v1/classes/${item.id}`);ElMessage.success("班级已删除");await load();}catch(cause){if(cause!=="cancel"&&cause!=="close")ElMessage.error(cause instanceof Error?cause.message:"删除失败");}}
function openImport(item?:Classroom){Object.assign(importForm,{classId:item?.id,studentNoField:"学号",nameField:"姓名"});file.value=null;importResult.value=null;importDialog.value=true;}
function chooseFile(event:Event){const next=(event.target as HTMLInputElement).files?.[0]??null;if(next&&!/\.(csv|xls|xlsx)$/i.test(next.name)){ElMessage.error("仅支持 csv、xls、xlsx 文件");return;}file.value=next;importResult.value=null;}
async function importStudents(){if(!file.value||!importForm.classId){ElMessage.warning("请选择目标班级和名册文件");return;}const body=new FormData();body.append("classId",String(importForm.classId));body.append("studentNoField",importForm.studentNoField);body.append("nameField",importForm.nameField);body.append("file",file.value);importing.value=true;try{importResult.value=await adminPost<ImportResult>("/api/admin/v1/students/import",body);ElMessage.success("导入完成");await load();}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"导入失败");}finally{importing.value=false;}}
watch(()=>route.fullPath,()=>{void load();if(!classId.value)void loadTeachers();},{immediate:true});
</script>

<template><section class="class-page page-container">
  <template v-if="!classId"><el-card shadow="never"><div class="toolbar management-inline-toolbar"><el-input v-model="searchText" clearable placeholder="搜索班级名称" @keyup.enter="keyword=searchText;load()"/><el-button @click="keyword=searchText;load()">搜索</el-button><div class="management-card-actions"><header class="page-heading"><div class="actions"><el-button v-if="classId" @click="router.push(adminPath('/classes'))">返回列表</el-button><el-button v-if="!classId" @click="openImport()">导入学生</el-button><el-button v-if="!classId" type="primary" @click="openCreate">创建班级</el-button><el-button v-if="classId" @click="detail&&openEdit(detail)">编辑班级</el-button><el-button v-if="classId" @click="openImport(detail??undefined)">导入学生</el-button></div></header></div></div><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="name" label="班级名称" min-width="170"/><el-table-column prop="teacherName" label="教师" min-width="140"><template #default="{row}">{{row.teacherName||'-'}}</template></el-table-column><el-table-column prop="memberCount" label="人数" width="90"/><el-table-column label="加入" width="100"><template #default="{row}"><el-tag :type="row.joinEnabled?'success':'info'">{{row.joinEnabled?'开启':'关闭'}}</el-tag></template></el-table-column><el-table-column label="审核" width="100"><template #default="{row}"><el-tag :type="row.approvalRequired?'warning':'success'">{{row.approvalRequired?'需要':'自动'}}</el-tag></template></el-table-column><el-table-column label="创建时间" min-width="170"><template #default="{row}">{{formatDisplayDateTime(row.createdAt)}}</template></el-table-column><el-table-column label="操作" min-width="230" fixed="right"><template #default="{row}"><el-button link type="primary" @click="router.push(adminPath(`/classes/${row.id}`))">查看</el-button><el-button link @click="openEdit(row)">编辑</el-button><el-button link @click="openImport(row)">导入</el-button><el-button link type="danger" @click="deleteClass(row)">删除</el-button></template></el-table-column></el-table></el-card></template>
  <template v-else><el-row :gutter="14"><el-col :xs="24" :sm="8"><el-card shadow="never"><el-statistic title="班级 ID" :value="detail?.id??0"/></el-card></el-col><el-col :xs="24" :sm="8"><el-card shadow="never"><el-statistic title="学生人数" :value="detail?.memberCount??0"/></el-card></el-col><el-col :xs="24" :sm="8"><el-card shadow="never"><div class="summary-label">负责教师</div><strong>{{detail?.teacherName||'-'}}</strong><div><el-tag :type="detail?.joinEnabled?'success':'info'">{{detail?.joinEnabled?'允许加入':'关闭加入'}}</el-tag></div></el-card></el-col></el-row><el-card shadow="never"><template #header><div class="management-card-heading"><div class="management-card-title"><strong>学生成员</strong></div><div class="management-card-actions"><header class="page-heading"><div class="actions"><el-button v-if="classId" @click="router.push(adminPath('/classes'))">返回列表</el-button><el-button v-if="!classId" @click="openImport()">导入学生</el-button><el-button v-if="!classId" type="primary" @click="openCreate">创建班级</el-button><el-button v-if="classId" @click="detail&&openEdit(detail)">编辑班级</el-button><el-button v-if="classId" @click="openImport(detail??undefined)">导入学生</el-button></div></header></div></div></template><el-table v-loading="loading" :data="detail?.members??[]" stripe><el-table-column prop="username" label="用户名" min-width="150"/><el-table-column prop="displayName" label="姓名" min-width="150"/><el-table-column prop="studentNo" label="学号" min-width="140"/><el-table-column prop="email" label="邮箱" min-width="180"/><el-table-column prop="source" label="来源" width="120"/><el-table-column label="加入时间" min-width="175"><template #default="{row}">{{formatDisplayDateTime(row.joinedAt)}}</template></el-table-column></el-table><el-empty v-if="!loading&&!detail?.members?.length" description="班级暂无学生"/></el-card></template>
  
<el-dialog class="qoj-management-dialog" v-model="dialog" :title="editing?'编辑班级':'创建班级'" width="620px"><el-form label-position="top"><el-form-item label="班级名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="班级介绍"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="教师" required><el-select v-model="form.teacherId" filterable remote :remote-method="loadTeachers" :loading="teacherLoading" placeholder="搜索教师"><el-option v-for="item in teachers" :key="item.id" :value="item.id" :label="`${item.displayName||item.username}${item.username?`（${item.username}）`:''}`"/></el-select></el-form-item><div class="switches"><el-form-item label="允许学生申请"><el-switch v-model="form.joinEnabled"/></el-form-item><el-form-item label="申请需要审批"><el-switch v-model="form.approvalRequired"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
  <el-dialog class="qoj-management-dialog" v-model="importDialog" title="导入学生名册" width="720px"><el-alert type="info" :closable="false" title="仅支持 CSV、XLS、XLSX。首行必须是表头，必需字段为学号和姓名；其他列会保存为学生扩展资料，不导入邮箱。"/><el-form label-position="top" class="import-form"><el-form-item label="目标班级" required><el-select v-model="importForm.classId"><el-option v-for="item in rows" :key="item.id" :value="item.id" :label="item.name"/></el-select></el-form-item><el-form-item label="导入文件" required><input type="file" accept=".csv,.xls,.xlsx" @change="chooseFile"><span v-if="file" class="file-name">{{file.name}}</span></el-form-item><div class="switches"><el-form-item label="学号字段"><el-input v-model="importForm.studentNoField"/></el-form-item><el-form-item label="姓名字段"><el-input v-model="importForm.nameField"/></el-form-item></div><p class="muted">示例表头：学号,姓名,手机号,专业,备注</p></el-form><StudentImportCredentials v-if="importResult" :successes="importResult.successes"/><el-card v-if="importResult" shadow="never"><p>成功 {{importResult.successCount}} 人，失败 {{importResult.failureCount}} 行</p><el-table v-if="importResult.errors?.length" :data="importResult.errors" stripe><el-table-column prop="rowNumber" label="行号" width="90"/><el-table-column prop="studentNo" label="学号" width="150"/><el-table-column prop="reason" label="原因"/></el-table></el-card><template #footer><el-button @click="importDialog=false">关闭</el-button><el-button type="primary" :loading="importing" @click="importStudents">开始导入</el-button></template></el-dialog>
  </section></template>

<style scoped>.class-page{display:flex;flex-direction:column;gap:16px}.page-heading,.actions,.toolbar,.switches{display:flex;align-items:center;justify-content:space-between;gap:10px}.page-heading h1{margin:0;font-size:22px}.page-heading p,.muted{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.toolbar{justify-content:flex-start;margin-bottom:12px}.toolbar .el-input{max-width:320px}.switches{justify-content:flex-start}.switches>*{flex:1}.el-select{width:100%}.import-form{margin-top:15px}.file-name{margin-left:8px;color:var(--el-text-color-secondary)}.summary-label{color:var(--el-text-color-secondary);font-size:13px;margin-bottom:10px}@media(max-width:700px){.page-heading,.actions{align-items:flex-start;flex-wrap:wrap}.switches{flex-direction:column;align-items:stretch}}</style>
